        } else if (type.equals(LocalDateTime.class)) {
            return DateKit.toLocalDateTime(value, "yyyy-MM-dd HH:mm:ss");
        } else if (type instanceof Class && ((Class) type).isEnum()){
            return Enum.valueOf((Class)type,value);
        }
        return value;
    }

