                    }
                }
            }
            argsMap.remove(BladeConst.ENV_KEY_APP_ENV);
        }

        this.environment.set(BladeConst.ENV_KEY_APP_ENV, envName);

        this.register(this.environment);

        // load terminal param
        if (BladeKit.isEmpty(args)) {
